    printf("cmatrix 1.0\n");
}

static void init_matrix(void) {
    int i;
    num_chars = 0;
    for (i = 0; i < MAX_CHARS; i++) {
        char_x[i] = 0;
        char_y[i] = 0;
        char_color[i] = 0;
        char_data[i] = ' ';
        char_active[i] = 0;
    }
}

static void reset_matrix(void) {
    int i;
