        char_x[i] = 0;
        char_y[i] = 0;
        char_color[i] = 0;
        char_data[i] = ' ';
        char_active[i] = 0;
    }
}

static void update_matrix(void) {
    int i;
    int new_y;
    int new_x;

    for (i = 0; i < num_chars; i++) {
        if (!char_active[i]) continue;

        if (old_style) {
            new_y = char_y[i] + 1;
            new_x = char_x[i];
        } else {
            new_y = char_y[i] + 1;
            new_x = char_x[i] + (rand() % 3 - 1);
        }

        if (new_y >= height - 1) {
            new_y = 0;
            new_x = rand() % width;
        }

        char_y[i] = new_y;
        char_x[i] = new_x;

        if (chars_change && !old_style) {
            char_data[i] = matrix_char_set[rand() % (strlen(matrix_char_set) - 1)];
        }
    }
}

static void draw_matrix(void) {
    int i;
    int color;
    int bold;

    for (i = 0; i < num_chars; i++) {
        if (!char_active[i]) continue;

        color = char_color[i];
        bold = 0;

        if (bold_chars && rand() % 100 < 5) {
            bold = 1;
        }
        if (all_bold) {
            bold = 1;
        }
        if (no_bold) {
            bold = 0;
        }

        if (rainbow) {
            color = (color + 1) % 8;
        }

        if (lambda_mode) {
            char_data[i] = 'λ';
        }

        if (use_shadows) {
            printf("\033[%d;%dH\033[30m\033[1;%dH\033[37m", char_x[i], char_y[i], char_x[i]);
        } else {
            printf("\033[%d;%dH\033[%d;%dm", char_x[i], char_y[i], color, bold ? 1 : 0);
        }

        printf("%c", char_data[i]);
    }
}

static void init_terminal(void) {
    struct termios oldt, newt;

    if (tcgetattr(STDIN_FILENO, &oldt) == -1) {
        return;
    }

    newt = oldt;
    newt.c_lflag &= ~(ECHO | ICANON);
    newt.c_cc[VMIN] = 0;
    newt.c_cc[VTIME] = 0;

    if (tcsetattr(STDIN_FILENO, TCSANOW, &newt) == -1) {
        return;
    }
}

static void restore_terminal(void) {
    struct termios oldt;

    if (tcgetattr(STDIN_FILENO, &oldt) == -1) {
        return;
    }

    tcsetattr(STDIN_FILENO, TCSANOW, &oldt);
}

